#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Swap the bass-band pulse for a spectral-FLUX (onset) pulse over kick+snare bands,
so the artwork follows both the kick and the snare and rests on sustained/breakdowns."""
import sys
SRC = "script.js"
c = open(SRC, encoding="utf-8").read()

OLD = (
'  // ---- beat pulse: artwork reacts to the REAL drums. Bass-band energy from the\n'
'  // ---- shared analyser -> attack/decay envelope -> scale + brightness flash.\n'
'  // ---- A silence gate eases it to still when there is no beat (breakdowns /\n'
'  // ---- ambient / quiet), so it pulses in time with the kick and stops otherwise.\n'
'  let beatPulseRaf = null;\n'
'  let _bassFreq = null, _bassEnv = 0, _bassPeak = 0.001, _bassFloor = 0, _beatGate = 0;\n'
'  function applyBeatPulseStrength(){\n'
'    const s = clamp(gs.beatPulseStrength != null ? gs.beatPulseStrength : 35, 0, 100) / 100;\n'
'    el.player.style.setProperty(\'--beat-pulse-max\', String(0.015 + s * 0.055));  // 1.5%-7% scale\n'
'    el.player.style.setProperty(\'--beat-flash-max\', String(0.05 + s * 0.20));   // 5%-25% brightness\n'
'  }\n'
'  function beatPulseLoop(){\n'
'    beatPulseRaf = null;\n'
'    const t = demoPlaylist[state.currentIndex];\n'
'    const m = state.master || el.audio;\n'
'    const enabled = gs.beatPulse !== false && t && m && !m.paused;\n'
'    if (enabled){\n'
'      const a = ensureVizGraph();               // shared analyser (created on first play)\n'
'      if (a){\n'
'        if (!_bassFreq || _bassFreq.length !== a.frequencyBinCount) _bassFreq = new Uint8Array(a.frequencyBinCount);\n'
'        a.getByteFrequencyData(_bassFreq);\n'
'        // kick / low-band energy (bins ~1-6, ~80-520 Hz at fftSize 512)\n'
'        const hi = Math.max(2, Math.min(6, _bassFreq.length));\n'
'        let sum = 0; for (let i = 1; i < hi; i++) sum += _bassFreq[i];\n'
'        const bass = (sum / (hi - 1)) / 255;    // 0..1 instantaneous\n'
'        // adaptive normalization: peak chases loud hits fast & decays slow; floor drifts\n'
'        _bassPeak += (bass - _bassPeak) * (bass > _bassPeak ? 0.35 : 0.01);\n'
'        _bassFloor += (bass - _bassFloor) * 0.004;\n'
'        const range = _bassPeak - _bassFloor;\n'
'        const lvl = range > 0.002 ? clamp((bass - _bassFloor) / range, 0, 1) : 0;\n'
'        // attack (snap on the hit) / decay (settle after) -> the "thump"\n'
'        const coef = lvl > _bassEnv ? 0.5 : 0.12;\n'
'        _bassEnv += (lvl - _bassEnv) * coef;\n'
'        // gate: only pulse when there is real beat energy; eased in/out so it\n'
'        // starts and stops smoothly with the drums (still during breakdowns)\n'
'        const targetGate = (range > 0.05 && _bassPeak > 0.05) ? 1 : 0;\n'
'        _beatGate += (targetGate - _beatGate) * 0.06;\n'
'        const max = parseFloat(getComputedStyle(el.player).getPropertyValue(\'--beat-pulse-max\')) || 0.04;\n'
'        const fmax = parseFloat(getComputedStyle(el.player).getPropertyValue(\'--beat-flash-max\')) || 0.15;\n'
'        const e = _bassEnv * _beatGate;\n'
'        el.player.style.setProperty(\'--beat-pulse\', String(1 + e * max));\n'
'        el.player.style.setProperty(\'--beat-flash\', String(1 + e * fmax));\n'
'      } else {\n'
'        el.player.style.setProperty(\'--beat-pulse\', \'1\');\n'
'        el.player.style.setProperty(\'--beat-flash\', \'1\');\n'
'      }\n'
'    } else {\n'
'      // not playing / disabled -> ease to still; reset envelope so it snaps on resume\n'
'      _bassEnv *= 0.85; _beatGate *= 0.9;\n'
'      el.player.style.setProperty(\'--beat-pulse\', \'1\');\n'
'      el.player.style.setProperty(\'--beat-flash\', \'1\');\n'
'    }\n'
'    beatPulseRaf = requestAnimationFrame(beatPulseLoop);'
)

NEW = (
'  // ---- beat pulse: artwork follows the DRUMS. Spectral FLUX (onset strength) is\n'
'  // ---- measured over a KICK band + a SNARE band each frame -> attack/decay\n'
'  // ---- envelope -> scale + brightness flash. Flux fires on every drum transient\n'
'  // ---- (kick OR snare) regardless of frequency/loudness, and falls to ~0 on\n'
'  // ---- sustained/beatless audio, so the art moves with the hits and rests in\n'
'  // ---- breakdowns/quiet. Relaxed gate + a touch more depth so it reads clearly.\n'
'  let beatPulseRaf = null;\n'
'  let _drumFreq = null, _drumPrev = null, _drumGotPrev = false;\n'
'  let _drumEnv = 0, _drumPeak = 0.001, _drumFloor = 0, _drumGate = 0;\n'
'  function applyBeatPulseStrength(){\n'
'    const s = clamp(gs.beatPulseStrength != null ? gs.beatPulseStrength : 35, 0, 100) / 100;\n'
'    el.player.style.setProperty(\'--beat-pulse-max\', String(0.02 + s * 0.06));   // 2%-8% scale\n'
'    el.player.style.setProperty(\'--beat-flash-max\', String(0.06 + s * 0.22));   // 6%-28% brightness\n'
'  }\n'
'  function beatPulseLoop(){\n'
'    beatPulseRaf = null;\n'
'    const t = demoPlaylist[state.currentIndex];\n'
'    const m = state.master || el.audio;\n'
'    const enabled = gs.beatPulse !== false && t && m && !m.paused;\n'
'    if (enabled){\n'
'      const a = ensureVizGraph();               // shared analyser (created on first play)\n'
'      if (a){\n'
'        if (!_drumFreq || _drumFreq.length !== a.frequencyBinCount){\n'
'          _drumFreq = new Uint8Array(a.frequencyBinCount);\n'
'          _drumPrev = new Uint8Array(a.frequencyBinCount);\n'
'          _drumGotPrev = false;\n'
'        }\n'
'        a.getByteFrequencyData(_drumFreq);\n'
'        // spectral flux = sum of POSITIVE frame-to-frame rises. A drum hit is a\n'
'        // sharp rise, so flux peaks on every onset. Two bands: KICK + SNARE crack.\n'
'        let flux = 0;\n'
'        const kHi = Math.min(5, _drumFreq.length);            // kick ~80-430 Hz\n'
'        for (let i = 1; i < kHi; i++){ const d = _drumFreq[i] - _drumPrev[i]; if (d > 0) flux += d; }\n'
'        const sLo = Math.min(10, _drumFreq.length);           // snare crack ~850 Hz\n'
'        const sHi = Math.min(46, _drumFreq.length);           //   up to ~4 kHz\n'
'        for (let i = sLo; i < sHi; i++){ const d = _drumFreq[i] - _drumPrev[i]; if (d > 0) flux += d; }\n'
'        _drumPrev.set(_drumFreq);                             // stash for next frame\n'
'        if (!_drumGotPrev){ _drumGotPrev = true; flux = 0; }  // skip first-frame spike\n'
'        flux = flux / 255;\n'
'        // adaptive normalization: peak chases hits fast, decays slow; floor drifts\n'
'        _drumPeak += (flux - _drumPeak) * (flux > _drumPeak ? 0.35 : 0.012);\n'
'        _drumFloor += (flux - _drumFloor) * 0.006;\n'
'        const range = _drumPeak - _drumFloor;\n'
'        const lvl = range > 0.002 ? clamp((flux - _drumFloor) / range, 0, 1) : 0;\n'
'        // attack (snap on the hit) / decay (settle after) -> the "thump"\n'
'        const coef = lvl > _drumEnv ? 0.55 : 0.14;\n'
'        _drumEnv += (lvl - _drumEnv) * coef;\n'
'        // gate: pulse only when there are real drum onsets; eased so it starts\n'
'        // and stops smoothly (still during breakdowns / sustained / silence)\n'
'        const targetGate = (range > 0.02 && _drumPeak > 0.02) ? 1 : 0;\n'
'        _drumGate += (targetGate - _drumGate) * 0.08;\n'
'        const max = parseFloat(getComputedStyle(el.player).getPropertyValue(\'--beat-pulse-max\')) || 0.05;\n'
'        const fmax = parseFloat(getComputedStyle(el.player).getPropertyValue(\'--beat-flash-max\')) || 0.18;\n'
'        const e = _drumEnv * _drumGate;\n'
'        el.player.style.setProperty(\'--beat-pulse\', String(1 + e * max));\n'
'        el.player.style.setProperty(\'--beat-flash\', String(1 + e * fmax));\n'
'      } else {\n'
'        el.player.style.setProperty(\'--beat-pulse\', \'1\');\n'
'        el.player.style.setProperty(\'--beat-flash\', \'1\');\n'
'      }\n'
'    } else {\n'
'      // not playing / disabled -> ease to still; reset envelope so it snaps on resume\n'
'      _drumEnv *= 0.85; _drumGate *= 0.9;\n'
'      el.player.style.setProperty(\'--beat-pulse\', \'1\');\n'
'      el.player.style.setProperty(\'--beat-flash\', \'1\');\n'
'    }\n'
'    beatPulseRaf = requestAnimationFrame(beatPulseLoop);'
)

n = c.count(OLD)
if n != 1:
    print("ABORTED: expected 1 match, found %d" % n); sys.exit(1)
open(SRC, "w", encoding="utf-8").write(c.replace(OLD, NEW))
print("OK — beat pulse now follows kick + snare via spectral flux")
